// Pull each dataset by node name. The five getAll nodes run in a serial
// chain (Tracker -> Metrics -> Planner -> Job Tasks -> Job Opportunities ->
// this node), each with alwaysOutputData so an empty database still lets the
// chain continue (emitting a single placeholder {} item instead of halting
// execution).
// dval() normalizes Notion date properties, which can come back either as
// a plain ISO string or as an object like { start, end, time_zone }.
const dval = (v) => (v && typeof v === 'object') ? (v.start ?? null) : (v || null);

// Notion select properties can arrive as a bare string or as an object
// ({ id, name, color }), same ambiguity as dates. Used for Status/Source.
const selVal = (v) => (v && typeof v === 'object') ? (v.name ?? v.value ?? '') : (v || '');

// The Notion node's simplified output flattens every property to
// `property_` + lowercase name (spaces -> underscores) and always includes
// a real page `id`. A placeholder {} item from alwaysOutputData has
// neither, so this filters those out without hardcoding a property name.
function hasRow(row) {
  return !!(row && row.id && Object.keys(row).some((k) => k.startsWith('property_')));
}

// Free-text values from Notion (job title, company, why, etc.) are
// untrusted content that lands directly in HTML — escape it so a stray
// "&" or "<" in a job title can't break the markup.
function escapeHtml(str) {
  return String(str).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

const trackerRows = $('Get Tracker Rows').all().map((i) => i.json).filter(hasRow);
const metricsRows = $('Get Metrics Rows').all().map((i) => i.json).filter(hasRow);
const plannerRows = $('Get Planner Rows').all().map((i) => i.json).filter(hasRow);
const jobTasksRows = $('Get Job Tasks Rows').all().map((i) => i.json).filter(hasRow);
// ASSUMPTION: the new "Job Opportunities" Notion database is wired into the
// workflow as a getAll node named "Get Job Opportunities Rows", following
// the same alwaysOutputData convention as the other four. That node does
// not exist in the live workflow yet (the database itself is still being
// built) — this code only has to be correct once it's wired in, and degrade
// to the empty state until then.
const jobOpportunityRows = $('Get Job Opportunities Rows').all().map((i) => i.json).filter(hasRow);

const today = $now.setZone('Europe/London').startOf('day');
const weekAgo = today.minus({ days: 7 });

// Window = last 7 full days before today (previous Mon-Sun when run on a
// Monday morning).
function inWindow(rawDate) {
  const dateStr = dval(rawDate);
  if (!dateStr) return false;
  const d = DateTime.fromISO(String(dateStr), { zone: 'Europe/London' }).startOf('day');
  if (!d.isValid) return false;
  return d >= weekAgo && d < today;
}

function isOverdue(row) {
  if (row.property_done) return false;
  const dateStr = dval(row.property_date);
  if (!dateStr) return false;
  const d = DateTime.fromISO(String(dateStr), { zone: 'Europe/London' }).startOf('day');
  return d.isValid && d < today;
}

let applicationsSubmitted = 0;
let outreachSent = 0;
let repliesReceived = 0;

for (const row of trackerRows) {
  if (inWindow(row.property_applied_date)) applicationsSubmitted++;
  if (inWindow(row.property_outreach_sent)) outreachSent++;
  if (inWindow(row.property_reply_received)) repliesReceived++;
}

let plannerTasksOverdue = 0;
for (const row of plannerRows) {
  if (isOverdue(row)) plannerTasksOverdue++;
}

let jobTasksOverdue = 0;
for (const row of jobTasksRows) {
  if (isOverdue(row)) jobTasksOverdue++;
}

// --- Job Opportunities (hero section) -------------------------------------
// Contract: Job (title) | Company (text) | Location (text) | Salary (text,
// empty when not stated) | Fit Score (number 0-100) | Why (text) | URL (url)
// | Job ID (text) | Source (select) | Seniority (text) | Status (select:
// New/Shortlisted/Applied/Dismissed) | First Seen (date).
function normalizeJob(row) {
  return {
    title: row.property_job || 'Untitled role',
    company: row.property_company || '',
    location: row.property_location || '',
    // Empty/missing Salary means "not stated" — never inferred, never filled in.
    salary: (row.property_salary || '').toString().trim(),
    fitScore: Math.max(0, Math.min(100, Math.round(Number(row.property_fit_score) || 0))),
    why: row.property_why || '',
    url: row.property_url || '',
    seniority: row.property_seniority || '',
    // Notion page id, used to build the "I applied" webhook link. Missing on
    // a malformed row -> that job just renders without the link (see
    // appliedLinkHtml), never with a broken/empty-id URL.
    pageId: row.id || '',
  };
}

const SPOTLIGHT_THRESHOLD = 85;
const MATCH_FLOOR = 60;
const MAX_TOP_MATCHES = 5;
const MIN_MATCHES_BEFORE_SLIM = 3;

// Eligible = Status "New" and First Seen inside this digest's window.
const eligibleJobs = jobOpportunityRows
  .filter((row) => selVal(row.property_status) === 'New' && inWindow(row.property_first_seen))
  .map(normalizeJob)
  .sort((a, b) => b.fitScore - a.fitScore);

// Spotlight is the single best job IF it clears the bar — never the
// best-of-a-bad-week promoted to look urgent. It's pulled out of the list
// below it so it isn't shown twice.
const spotlightJob = eligibleJobs.length > 0 && eligibleJobs[0].fitScore >= SPOTLIGHT_THRESHOLD
  ? eligibleJobs[0]
  : null;
// A low-fit job (e.g. 22/100) diluting the match list defeats the point of
// the section, so anything below MATCH_FLOOR never enters it — no padding
// to hit a minimum count.
const qualifiedMatches = (spotlightJob ? eligibleJobs.slice(1) : eligibleJobs)
  .filter((j) => j.fitScore >= MATCH_FLOOR);
const topMatches = qualifiedMatches.slice(0, MAX_TOP_MATCHES);
// "Pipeline has no data yet" and "we looked, nothing was good enough" are
// different situations and get different copy below.
const pipelineEmpty = eligibleJobs.length === 0;
const nothingGoodThisWeek = !pipelineEmpty && !spotlightJob && qualifiedMatches.length === 0;

// A slim bar built from two table cells (filled / unfilled) — no SVG, no
// images. The numeric "Fit N/100" label always sits next to it so meaning
// survives a dark-mode colour inversion, not just the bar colour.
function fitIndicatorHtml(score) {
  const filled = Math.round((score / 100) * 80);
  const unfilled = 80 - filled;
  const barColor = score >= 85 ? '#15803d' : score >= 70 ? '#2563eb' : '#9ca3af';
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
<td style="padding-right:8px;">
<table role="presentation" width="80" cellpadding="0" cellspacing="0" border="0"><tr>
<td width="${filled}" height="6" style="background-color:${barColor};font-size:0;line-height:6px;">&nbsp;</td>
<td width="${unfilled}" height="6" style="background-color:#e5e7eb;font-size:0;line-height:6px;">&nbsp;</td>
</tr></table>
</td>
<td style="font-size:12px;font-weight:600;color:#374151;white-space:nowrap;">Fit ${score}/100</td>
</tr></table>`;
}

// Pulls the numeric amounts out of a raw salary string so we can guess
// whether it's actually a day rate wearing a salary-shaped column. Handles
// "K" shorthand ("£35K-£45K" -> [35000, 45000]) and comma thousands
// ("£55,000" -> [55000]). Never used to alter the displayed string, only to
// decide whether to append a hedge next to it.
function parseSalaryNumbers(str) {
  const matches = String(str).match(/[\d,]+(?:\.\d+)?\s*[kK]?/g);
  if (!matches) return [];
  return matches
    .map((m) => {
      const isK = /[kK]\s*$/.test(m);
      const num = parseFloat(m.replace(/,/g, '').replace(/[kK]\s*$/, ''));
      return Number.isNaN(num) ? null : (isK ? num * 1000 : num);
    })
    .filter((n) => n !== null);
}

// Salary honesty rule: blank means "not stated", never a guess. Separately,
// LinkedIn-sourced figures under ~£2,000 are almost always a day rate, not
// an annual salary — flagged with a hedge (not a rewrite) so "£500-£550"
// next to "£65,000 - £75,000" doesn't read as an absurd annual figure.
function salaryHtml(salary) {
  if (!salary) return `<span style="color:#9ca3af;font-style:italic;">Salary not stated</span>`;
  const nums = parseSalaryNumbers(salary);
  const likelyDayRate = nums.length > 0 && Math.max(...nums) < 2000;
  const qualifier = likelyDayRate
    ? ` <span style="color:#9ca3af;font-style:italic;">(as stated &mdash; likely a day rate)</span>`
    : '';
  return `<span style="color:#111827;font-weight:600;">${escapeHtml(salary)}</span>${qualifier}`;
}

function applyButtonHtml(job, { bg, label, padY, padX, fontSize }) {
  if (!job.url) return '';
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
<td style="background-color:${bg};border-radius:4px;">
<a href="${escapeHtml(job.url)}" style="display:inline-block;padding:${padY}px ${padX}px;font-size:${fontSize}px;font-weight:700;color:#ffffff;text-decoration:none;">${label} &rarr;</a>
</td>
</tr></table>`;
}

// Bookkeeping action, not the primary CTA — plain underlined text, muted
// grey, deliberately smaller than the Apply button next to it. Copy makes
// the one-way effect explicit: this marks the row Applied in Notion, which
// drops it out of next week's eligibleJobs window (see normalizeJob/
// eligibleJobs above).
// Never emitted without a real pageId — a malformed Notion row (or a job
// that predates this field) just loses the link, not gains a broken one.
function appliedLinkHtml(job, fontSize) {
  if (!job.pageId) return '';
  const url = `http://localhost:5678/webhook/job-applied?job=${encodeURIComponent(job.pageId)}`;
  return `<a href="${url}" style="font-size:${fontSize}px;color:#6b7280;text-decoration:underline;">I applied &rarr;</a>`;
}

// Combines the Apply button with the secondary "I applied" link in one row
// so they stay vertically aligned. Either half can be absent (no url, no
// pageId) without leaving a stray empty cell.
function actionsRowHtml(job, opts) {
  const applyHtml = applyButtonHtml(job, opts);
  const appliedHtml = appliedLinkHtml(job, Math.max(11, opts.fontSize - 1));
  if (!applyHtml && !appliedHtml) return '';
  const cells = [];
  if (applyHtml) cells.push(`<td style="vertical-align:middle;">${applyHtml}</td>`);
  if (appliedHtml) cells.push(`<td style="vertical-align:middle;padding-left:${applyHtml ? 10 : 0}px;">${appliedHtml}</td>`);
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>${cells.join('')}</tr></table>`;
}

function jobMetaHtml(job) {
  const bits = [job.company, job.location].filter(Boolean).map(escapeHtml).join(' &middot; ');
  const withSeniority = job.seniority ? `${bits ? bits + ' &middot; ' : ''}${escapeHtml(job.seniority)}` : bits;
  return withSeniority
    ? `<tr><td style="font-size:12px;color:#6b7280;padding-bottom:6px;">${withSeniority}</td></tr>`
    : '';
}

function jobCardHtml(job, isLast) {
  return `<tr>
<td style="padding:12px 0;${isLast ? '' : 'border-bottom:1px solid #f3f4f6;'}">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
<tr><td style="font-size:15px;font-weight:700;color:#111827;padding-bottom:1px;">${escapeHtml(job.title)}</td></tr>
${jobMetaHtml(job)}
<tr><td style="padding-bottom:6px;">${fitIndicatorHtml(job.fitScore)}</td></tr>
<tr><td style="font-size:13px;padding-bottom:4px;">${salaryHtml(job.salary)}</td></tr>
${job.why ? `<tr><td style="font-size:13px;color:#374151;padding-bottom:8px;">${escapeHtml(job.why)}</td></tr>` : ''}
<tr><td>${actionsRowHtml(job, { bg: '#2563eb', label: 'Apply', padY: 7, padX: 14, fontSize: 12 })}</td></tr>
</table>
</td>
</tr>`;
}

// The spotlight badge pairs a colour (amber) with an explicit text label
// ("Spotlight") so its meaning doesn't depend on colour surviving an
// Outlook dark-mode inversion.
function spotlightBlockHtml(job) {
  return `<tr>
<td style="padding-bottom:16px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#fffbeb" style="background-color:#fffbeb;border:1px solid #fde68a;border-radius:6px;">
<tr>
<td style="padding:14px 16px;">
<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
<td style="font-size:11px;font-weight:700;letter-spacing:0.05em;text-transform:uppercase;color:#b45309;background-color:#fef3c7;border-radius:4px;padding:3px 8px;">&#9733; Spotlight &mdash; top pick this week</td>
</tr></table>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:10px;">
<tr><td style="font-size:17px;font-weight:700;color:#111827;padding-bottom:1px;">${escapeHtml(job.title)}</td></tr>
${jobMetaHtml(job)}
<tr><td style="padding-bottom:6px;">${fitIndicatorHtml(job.fitScore)}</td></tr>
<tr><td style="font-size:13px;padding-bottom:4px;">${salaryHtml(job.salary)}</td></tr>
${job.why ? `<tr><td style="font-size:13px;color:#374151;padding-bottom:10px;">${escapeHtml(job.why)}</td></tr>` : ''}
<tr><td>${actionsRowHtml(job, { bg: '#b45309', label: 'Apply now', padY: 9, padX: 18, fontSize: 13 })}</td></tr>
</table>
</td>
</tr>
</table>
</td>
</tr>`;
}

function sectionHeaderHtml(title) {
  return `<tr>
<td colspan="2" style="font-size:12px;font-weight:700;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-bottom:8px;">${title}</td>
</tr>`;
}

function topMatchesSectionHtml() {
  // Pipeline has literally no rows this week vs. we looked and nothing was
  // good enough — different situations, different copy, so the reader can tell
  // at a glance whether the pipeline is broken or the week was just weak.
  if (pipelineEmpty) {
    return `${sectionHeaderHtml('Top matches this week')}
<tr>
<td colspan="2" style="font-size:13px;color:#9ca3af;padding:2px 0;">No matches yet &mdash; the job pipeline just went live. This section fills in once roles start getting scored.</td>
</tr>`;
  }
  if (nothingGoodThisWeek) {
    const n = eligibleJobs.length;
    return `${sectionHeaderHtml('Top matches this week')}
<tr>
<td colspan="2" style="font-size:13px;color:#9ca3af;padding:2px 0;">Nothing cleared the bar this week &mdash; ${n} job${n === 1 ? '' : 's'} reviewed, none scored highly enough to surface.</td>
</tr>`;
  }

  // Fewer than 3 matches (but at least 1) reads as thin, not broken — the
  // heading says so rather than padding the list with sub-floor jobs.
  const title = qualifiedMatches.length > 0 && qualifiedMatches.length < MIN_MATCHES_BEFORE_SLIM
    ? 'Slim pickings this week'
    : 'Top matches this week';

  const spotlightHtml = spotlightJob ? spotlightBlockHtml(spotlightJob) : '';
  const cardsHtml = topMatches.length > 0
    ? topMatches.map((j, idx) => jobCardHtml(j, idx === topMatches.length - 1)).join('\n')
    : `<tr><td colspan="2" style="font-size:13px;color:#9ca3af;padding:4px 0;">No other matches this week.</td></tr>`;

  return `${spotlightHtml}
${sectionHeaderHtml(title)}
${cardsHtml}`;
}

// Classifier metrics.
// ASSUMPTION (not confirmed against a live execution, only against the
// classifier workflow that writes this database — see email-classifier.json):
// the Email Metrics Log has a "Category" select property and an
// "Auto-filed" checkbox property (true when confidence >= 80). Per the
// flattening convention above that becomes property_category (string) and
// property_auto-filed (boolean). If n8n's simplified output ever returns
// select fields as an object instead of a bare string, the category
// breakdown below would need a small dval()-style unwrap.
let classificationVolume = 0; // this week only
const categoryCounts = {};
for (const row of metricsRows) {
  if (inWindow(row.property_timestamp)) {
    classificationVolume++;
    const cat = selVal(row.property_category) || 'UNKNOWN';
    categoryCounts[cat] = (categoryCounts[cat] || 0) + 1;
  }
}

// Low-confidence rate and the review queue are running totals across every
// row ever logged, not just this week — a low-confidence email doesn't
// expire, so "how much needs review" is measured against everything
// outstanding, not this week's slice. This replaces the old "precision"
// metric, which was derived from the "Corrected" checkbox the user has
// never ticked and was therefore pinned at 100% forever.
const totalClassified = metricsRows.length;
// "Auto-filed" contains a hyphen, and n8n's flattening of hyphens is not
// something we could confirm without a live payload, so accept every
// plausible spelling. A silent key miss here would report 0 low-confidence
// forever -- exactly the failure mode the old precision metric had.
const autoFiledOf = (row) =>
  row['property_auto-filed'] ?? row.property_auto_filed ?? row.property_autofiled;
const lowConfidenceCount = metricsRows.filter((row) => autoFiledOf(row) === false).length;
const lowConfidenceRate = totalClassified > 0
  ? ((lowConfidenceCount / totalClassified) * 100).toFixed(1)
  : '0.0';
const reviewQueueUrl = 'https://www.notion.so/YOUR_EMAIL_METRICS_LOG_DATABASE_ID';

const weekStart = weekAgo.toFormat('d LLL yyyy');
const weekEndDate = today.minus({ days: 1 });

// Formats the digest window as "13–19 Jul 2026", collapsing the month/year
// when both ends fall in the same one and spelling both out otherwise.
function formatWeekRange(start, end) {
  if (start.hasSame(end, 'month') && start.hasSame(end, 'year')) {
    return `${start.toFormat('d')}–${end.toFormat('d LLL yyyy')}`;
  }
  if (start.hasSame(end, 'year')) {
    return `${start.toFormat('d LLL')} – ${end.toFormat('d LLL yyyy')}`;
  }
  return `${start.toFormat('d LLL yyyy')} – ${end.toFormat('d LLL yyyy')}`;
}

const weekRange = formatWeekRange(weekAgo, weekEndDate);
const subject = `Job search digest — week of ${weekRange}`;

// Neutral gray by default; amber only when something is actually overdue.
// Zero states stay gray so a quiet week reads as calm, not broken.
const jobOverdueColor = jobTasksOverdue > 0 ? '#b45309' : '#6b7280';
const plannerOverdueColor = plannerTasksOverdue > 0 ? '#b45309' : '#6b7280';

// Known classifier categories (from email-classifier.json's enum) get a
// friendly label and colour. Anything else (a future category, or a value
// this code didn't anticipate) still renders via the fallback, just in
// neutral gray, so an unmapped category can never break the email.
const CATEGORY_META = {
  ACTION_NEEDED: { label: 'Action needed', color: '#b45309', bg: '#fef3c7' },
  RECRUITER_REPLY: { label: 'Recruiter reply', color: '#15803d', bg: '#dcfce7' },
  JOB_ALERT: { label: 'Job alert', color: '#1d4ed8', bg: '#dbeafe' },
  JOB_CONFIRMATION: { label: 'Application confirmation', color: '#1d4ed8', bg: '#dbeafe' },
  JOB_REJECTION: { label: 'Rejection', color: '#4b5563', bg: '#f3f4f6' },
  FYI: { label: 'FYI', color: '#4b5563', bg: '#f3f4f6' },
  IGNORE: { label: 'Ignore', color: '#6b7280', bg: '#f3f4f6' },
};

const categoryOrder = Object.keys(categoryCounts).sort((a, b) => categoryCounts[b] - categoryCounts[a]);

function categoryRowHtml(cat) {
  const meta = CATEGORY_META[cat] || { label: cat, color: '#4b5563', bg: '#f3f4f6' };
  const count = categoryCounts[cat];
  return `<tr>
<td style="padding:3px 0;">
<table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
<td style="font-size:12px;font-weight:600;color:${meta.color};background-color:${meta.bg};border-radius:4px;padding:3px 8px;white-space:nowrap;">${meta.label}</td>
<td style="font-size:13px;color:#374151;padding-left:8px;">${count}</td>
</tr></table>
</td>
</tr>`;
}

const categoryBreakdownHtml = categoryOrder.length > 0
  ? categoryOrder.map(categoryRowHtml).join('\n')
  : `<tr><td style="font-size:13px;color:#9ca3af;padding:3px 0;">No emails classified this week</td></tr>`;

const classifierVolumeLine = classificationVolume > 0
  ? `${classificationVolume} email${classificationVolume === 1 ? '' : 's'} classified this week`
  : 'No emails classified this week';

const classifierSectionHtml = totalClassified > 0
  ? `<tr>
<td colspan="2" style="font-size:12px;font-weight:700;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-bottom:8px;">Email classifier</td>
</tr>
<tr>
<td colspan="2" style="font-size:14px;color:#374151;padding:2px 0;">${classifierVolumeLine}</td>
</tr>
<tr>
<td colspan="2" style="font-size:13px;color:#6b7280;padding:2px 0 10px;">${lowConfidenceCount} of ${totalClassified} all-time flagged low-confidence (${lowConfidenceRate}%) · <a href="${reviewQueueUrl}" style="color:#2563eb;text-decoration:underline;">${lowConfidenceCount} awaiting review &rarr;</a></td>
</tr>
<tr>
<td colspan="2">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
${categoryBreakdownHtml}
</table>
</td>
</tr>`
  : `<tr>
<td colspan="2" style="font-size:12px;font-weight:700;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-bottom:8px;">Email classifier</td>
</tr>
<tr>
<td colspan="2" style="font-size:13px;color:#9ca3af;padding:2px 0;">No data yet — stats start once the classifier logs its first email.</td>
</tr>`;

// Table-based, inline-styled layout for Outlook/Hotmail webmail compatibility
// (no external CSS/fonts/images, no flexbox/grid). Outer table is width=100%
// with a max-width cap on the inner card so it stays mobile-safe.
const html = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background-color:#f4f5f7;padding:24px 0;font-family:-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
<tr>
<td align="center">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="max-width:600px;width:100%;background-color:#ffffff;border-radius:8px;padding:24px;">
<tr>
<td style="font-size:22px;font-weight:700;color:#2563eb;padding-bottom:4px;">Job search digest</td>
</tr>
<tr>
<td style="font-size:13px;color:#6b7280;padding-bottom:20px;">${weekRange}</td>
</tr>
<tr>
<td style="padding-bottom:4px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
${topMatchesSectionHtml()}
</table>
</td>
</tr>
<tr>
<td style="border-top:1px solid #e5e7eb;font-size:0;line-height:0;padding:0;">&nbsp;</td>
</tr>
<tr>
<td style="padding-top:20px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
<tr>
<td align="center" width="33%" style="padding:8px 4px;">
<div style="font-size:28px;line-height:32px;font-weight:700;color:#111827;">${applicationsSubmitted}</div>
<div style="font-size:11px;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-top:4px;">Applications</div>
</td>
<td align="center" width="33%" style="padding:8px 4px;">
<div style="font-size:28px;line-height:32px;font-weight:700;color:#111827;">${outreachSent}</div>
<div style="font-size:11px;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-top:4px;">Outreach</div>
</td>
<td align="center" width="33%" style="padding:8px 4px;">
<div style="font-size:28px;line-height:32px;font-weight:700;color:#111827;">${repliesReceived}</div>
<div style="font-size:11px;letter-spacing:0.05em;text-transform:uppercase;color:#6b7280;padding-top:4px;">Replies</div>
</td>
</tr>
</table>
</td>
</tr>
<tr>
<td style="border-top:1px solid #e5e7eb;font-size:0;line-height:0;padding:0;">&nbsp;</td>
</tr>
<tr>
<td style="padding-top:20px;">
